findOne(id: number) {
  const note = this.notes.find((item) => item.id === id);

  if (!note) {
    throw new NotFoundException(`Note ${id} not found`);
  }

  return note;
}

import { IsInt, IsString, Min, MinLength } from 'class-validator';

export class CreateNoteDto {
  @IsInt()
  @Min(1)
  userId: number;

  @IsString()
  @MinLength(2)
  title: string;

  @IsString()
  @MinLength(1)
  content: string;
}

import { IsInt, IsOptional, IsString, Min, MinLength } from 'class-validator';

export class UpdateNoteDto {
  @IsOptional()
  @IsInt()
  @Min(1)
  userId?: number;

  @IsOptional()
  @IsString()
  @MinLength(2)
  title?: string;

  @IsOptional()
  @IsString()
  @MinLength(1)
  content?: string;
}

update(id: number, body: UpdateNoteDto) {
  const note = this.findOne(id);

  if (body.userId !== undefined) {
    const user = this.usersService.findOne(body.userId);
    note.userId = user.id;
  }

  Object.assign(note, {
    title: body.title ?? note.title,
    content: body.content ?? note.content,
  });

  this.logger.log(`updated note ${note.id}`);

  return note;
}

