import { BadRequestException, ConflictException, Injectable, NotFoundException } from '@nestjs/common';

create(body: CreateUserDto) {
  const normalizedName = body.name.trim().toLowerCase();
  const exists = this.users.some((user) => user.name.toLowerCase() === normalizedName);

  if (exists) {
    throw new ConflictException(`User name ${body.name} already exists`);
  }

  const user: User = {
    id: this.nextId,
    name: body.name,
    age: body.age,
  };

  this.nextId += 1;
  this.users.push(user);

  return user;
}

remove(id: number) {
  const note = this.findOne(id);

  this.notes = this.notes.filter((item) => item.id !== note.id);
  this.logger.log(`deleted note ${note.id}`);

  return {
    success: true,
    deletedId: note.id,
  };
}

