import { BadRequestException } from '@nestjs/common';
import { PositiveIntPipe } from './positive-int.pipe';

describe('PositiveIntPipe', () => {
  const pipe = new PositiveIntPipe();

  it('returns a number when value is a positive integer string', () => {
    expect(pipe.transform('12')).toBe(12);
  });

  it('throws BadRequestException when value is not a positive integer', () => {
    expect(() => pipe.transform('abc')).toThrow(BadRequestException);
    expect(() => pipe.transform('0')).toThrow(BadRequestException);
    expect(() => pipe.transform('-1')).toThrow(BadRequestException);
    expect(() => pipe.transform('1.5')).toThrow(BadRequestException);
  });
});

import { ValidationPipe } from '@nestjs/common';
import { Test, TestingModule } from '@nestjs/testing';
import { INestApplication } from '@nestjs/common';
import request from 'supertest';
import { AppModule } from './../src/app.module';

describe('Validation behavior (e2e)', () => {
  let app: INestApplication;

  beforeEach(async () => {
    const moduleFixture: TestingModule = await Test.createTestingModule({
      imports: [AppModule],
    }).compile();

    app = moduleFixture.createNestApplication();
    app.useGlobalPipes(
      new ValidationPipe({
        whitelist: true,
        forbidNonWhitelisted: true,
        transform: true,
      }),
    );
    await app.init();
  });

  afterEach(async () => {
    await app.close();
  });

  it('/users rejects invalid body', () => {
    return request(app.getHttpServer())
      .post('/users')
      .send({ name: 'A', age: 24 })
      .expect(400);
  });

  it('/users rejects extra body fields', () => {
    return request(app.getHttpServer())
      .post('/users')
      .send({ name: 'Charlie', age: 24, role: 'admin' })
      .expect(400);
  });

  it('/notes rejects invalid id', () => {
    return request(app.getHttpServer()).get('/notes/abc').expect(400);
  });
});

