export class FindUsersQueryDto {
  @IsOptional()
  @IsString()
  keyword?: string;

  @IsOptional()
  @Type(() => Number)
  @IsInt()
  @Min(1)
  page = 1;

  @IsOptional()
  @Type(() => Number)
  @IsInt()
  @Min(1)
  @Max(100)
  pageSize = 10;
}

import { FindUsersQueryDto } from './dto/find-users-query.dto';

@Get()
findAll(@Query() query: FindUsersQueryDto) {
  return this.usersService.findAll(query);
}

import { FindUsersQueryDto } from './dto/find-users-query.dto';

findAll(query: FindUsersQueryDto) {
  const keyword = query.keyword?.trim().toLowerCase();
  const filteredUsers = keyword
    ? this.users.filter((user) => user.name.toLowerCase().includes(keyword))
    : this.users;

  const page = query.page ?? 1;
  const pageSize = query.pageSize ?? 10;
  const start = (page - 1) * pageSize;
  const items = filteredUsers.slice(start, start + pageSize);

  return {
    items,
    page,
    pageSize,
    total: filteredUsers.length,
  };
}

@Type(() => Number)
  告诉 class-transformer 把 query 字符串转换成 number

@IsInt / @Min / @Max
  告诉 class-validator 转换后要满足什么规则

import { ValidationPipe } from '@nestjs/common';
import { NestFactory } from '@nestjs/core';
import { DocumentBuilder, SwaggerModule } from '@nestjs/swagger';
import { AppModule } from './app.module';

async function bootstrap() {
  const app = await NestFactory.create(AppModule);

  app.useGlobalPipes(
    new ValidationPipe({
      whitelist: true,
      forbidNonWhitelisted: true,
      transform: true,
    }),
  );

  const swaggerConfig = new DocumentBuilder()
    .setTitle('Notes API')
    .setDescription('NestJS learning project API')
    .setVersion('week-3')
    .build();

  const swaggerDocument = SwaggerModule.createDocument(app, swaggerConfig);
  SwaggerModule.setup('api-docs', app, swaggerDocument);

  const port = process.env.PORT ?? 3000;

  await app.listen(port);
  console.log(`Nest learning API is running on http://localhost:${port}`);
}

void bootstrap();

